async function logs() {
    const alive = pid => {
        try {
            process.kill(pid, 0);
            return true;
        } catch (e) {
            return e.code === 'EPERM';
        }
    };
    const read = file => {
        try {
            return JSON.parse(readFileSync(file, 'utf8'));
        } catch {
            return undefined;
        }
    };
    const out = [`co-review ${version()}`];
    const app = read(join(logsDir, 'app.json'));
    if (app?.pid) {
        out.push(`Desktop app: process ${app.pid} ${alive(app.pid) ? 'running' : 'not running'} (started ${app.started})`);
    }
