const PACKAGES = { pi: 'pi', omp: 'omp' };

/** Installs a bundled agent package with the harness's own installer. */
async function setup() {
    const harness = args[0];
    if (!PACKAGES[harness]) {
        throw new Error(`usage: co-review setup <${Object.keys(PACKAGES).join('|')}>`);
    }
