import { AbstractViewContribution, OpenViewArguments } from '@theia/core/lib/browser/shell/view-contribution';
import { StatusBar, StatusBarAlignment } from '@theia/core/lib/browser/status-bar/status-bar';
import { FrontendApplicationContribution } from '@theia/core/lib/browser/frontend-application-contribution';
import { KeybindingRegistry } from '@theia/core/lib/browser/keybinding';
import { QuickInputService, QuickPickItem } from '@theia/core/lib/browser/quick-input';
import { ConfirmDialog } from '@theia/core/lib/browser/dialogs';
import { confirmGitHubPost } from './github-preview';
import { CommandRegistry, CommandService } from '@theia/core/lib/common/command';
import { MenuModelRegistry } from '@theia/core/lib/common/menu';
import { MessageService } from '@theia/core/lib/common/message-service';
import { ClipboardService } from '@theia/core/lib/browser/clipboard-service';
import { SelectionService } from '@theia/core/lib/common/selection-service';
import { UriAwareCommandHandler } from '@theia/core/lib/common/uri-command-handler';
import URI from '@theia/core/lib/common/uri';
import { inject, injectable } from '@theia/core/shared/inversify';
import { EDITOR_CONTEXT_MENU } from '@theia/editor/lib/browser/editor-menu';
import { EditorManager } from '@theia/editor/lib/browser/editor-manager';
import { FileService } from '@theia/filesystem/lib/browser/file-service';
import { MonacoEditor } from '@theia/monaco/lib/browser/monaco-editor';
import { FileNavigatorContribution, NavigatorContextMenu } from '@theia/navigator/lib/browser/navigator-contribution';
import * as monaco from '@theia/monaco-editor-core';
import { AgentConfig, AgentSetting, CodeLocation, ReviewScope, ThreadIntent } from '../common/review-model';
import { DOCUMENT_NAMES } from '../common/patch';
import { OpenerService, open } from '@theia/core/lib/browser/opener-service';
import { ReviewService } from '../common/review-protocol';
import { ReviewCommands } from './review-commands';
import { fromMonacoRange, ReviewLocations } from './review-locations';
import { ReviewManager } from './review-manager';
import { ReviewWidget } from './review-widget';
import { ReviewEditorDecorator } from './review-editor-decorator';
import { ReviewNavigator } from './review-navigator';

export const REVIEW_CONTEXT_MENU_GROUP = [...EDITOR_CONTEXT_MENU, '0_co_review'];
export const REVIEW_NAVIGATOR_GROUP = [...NavigatorContextMenu.NAVIGATION, '0_co_review'];

@injectable()
export class ReviewContribution extends AbstractViewContribution<ReviewWidget> implements FrontendApplicationContribution {

    @inject(ReviewManager) protected readonly reviews: ReviewManager;
    @inject(ReviewService) protected readonly service: ReviewService;
    @inject(EditorManager) protected readonly editorManager: EditorManager;
    @inject(QuickInputService) protected readonly quickInput: QuickInputService;
    @inject(MessageService) protected readonly messages: MessageService;
    @inject(SelectionService) protected readonly selectionService: SelectionService;
    @inject(FileService) protected readonly fileService: FileService;
    @inject(ReviewLocations) protected readonly locations: ReviewLocations;
    @inject(StatusBar) protected readonly statusBar: StatusBar;
    @inject(CommandService) protected readonly commandService: CommandService;
    @inject(OpenerService) protected readonly openerService: OpenerService;
    @inject(ReviewEditorDecorator) protected readonly decorator: ReviewEditorDecorator;
    @inject(ReviewNavigator) protected readonly navigator: ReviewNavigator;
    @inject(ClipboardService) protected readonly clipboard: ClipboardService;
    @inject(FileNavigatorContribution) protected readonly fileNavigator: FileNavigatorContribution;

    constructor() {
        super({
            widgetId: ReviewWidget.ID,
            widgetName: ReviewWidget.LABEL,
            defaultWidgetOptions: { area: 'right', rank: 100 },
            toggleCommandId: ReviewCommands.TOGGLE_PANEL.id,
            toggleKeybinding: 'ctrlcmd+shift+alt+r'
        });
    }

    /** The panel opens on demand; a status bar entry shows the open threads and toggles it. */
    onStart(): void {
        const update = () => {
            const review = this.reviews.activeReview;
            const open = review?.threads.filter(t => t.status !== 'resolved').length ?? 0;
            this.statusBar.setElement('co-review', {
                text: `$(comment-discussion) ${review ? open : 'Review'}`,
                tooltip: review ? `${review.title}: ${open} open thread${open === 1 ? '' : 's'} — show/hide the Review panel` : 'Start a review',
                alignment: StatusBarAlignment.LEFT,
                priority: 100,
                command: ReviewCommands.TOGGLE_PANEL.id
            });
        };
        this.reviews.onDidChange(update);
        update();
        // Whether the file in the editor is viewed; click to toggle.
        const viewed = () => {
            const uri = this.editorManager.currentEditor?.editor.getResourceUri()?.toString();
            const review = this.reviews.activeReview;
            if (!uri || !review || review.bundle || !uri.startsWith('file:')) {
                this.statusBar.removeElement('co-review-viewed');
                return;
            }
            const done = this.reviews.isViewed(uri);
            this.statusBar.setElement('co-review-viewed', {
                text: done ? '$(pass-filled) Viewed' : '$(circle-large-outline) Not viewed',
                tooltip: done ? 'You marked this file as viewed; click to unmark' : 'Mark this file as viewed (⌘⌥V)',
                alignment: StatusBarAlignment.LEFT,
                priority: 99,
                command: ReviewCommands.TOGGLE_VIEWED.id
            });
        };
        this.reviews.onDidChange(viewed);
        this.editorManager.onCurrentEditorChanged(viewed);
        viewed();
    }

    /** Posts the review to its GitHub pull request, after the reviewer confirms what goes out and as what. */
    protected async postToGitHub(): Promise<void> {
        const review = this.reviews.activeReview;
        const github = await this.reviews.getGitHubTarget();
        if (!review || !github) {
            this.messages.warn('This review is not a GitHub pull request: its review directory needs a PR.md with `repo: <owner>/<name>` and `pr: <number>`.');
            return;
        }
        const label = { approve: 'Approve', 'request-changes': 'Request changes', comment: 'Comment' } as const;
        const picked = await this.quickInput.pick((Object.keys(label) as (keyof typeof label)[]).map(d => ({
            label: label[d], id: d, description: d === (review.verdict?.decision ?? 'comment') ? 'your verdict' : undefined
        })), { placeHolder: `Post to ${github.repo}#${github.number} as…` });
        if (!picked) {
            return;
        }
        let preview;
        try {
            preview = await this.reviews.previewGitHubPost(picked.id as keyof typeof label, review.verdict?.summary);
        } catch (e) {
            this.messages.error(String(e instanceof Error ? e.message : e));
            return;
        }
        const edits = await confirmGitHubPost(github, preview);
        if (!edits) {
            return;
        }
        try {
            const posted = await this.reviews.postToGitHub(picked.id as keyof typeof label, review.verdict?.summary, edits);
            const action = await this.messages.info(`Posted to GitHub: ${posted.comments} line comment${posted.comments === 1 ? '' : 's'}`
                + `${posted.inBody ? `, ${posted.inBody} in the body` : ''}.${posted.notes.length ? ` ${posted.notes.join(' ')}` : ''}`, 'Open on GitHub');
            if (action) {
                window.open(posted.url, '_blank', 'noopener');
            }
        } catch (e) {
            this.messages.error(String(e instanceof Error ? e.message : e));
        }
    }

    /**
     * Opens the active review's overview page, its front page: the change or repository, the agent's overview, every
     * finding and comment. False for a review directory without patches (its document is its front page).
     */
    protected async openOverview(): Promise<boolean> {
        const uri = await this.reviews.writeOverview();
        if (uri) {
            await this.navigator.open({ kind: 'document', uri });
        }
        return !!uri;
    }

    /** Toggles "viewed" for a file or folder (all of its files), or the file in the editor. */
    protected async toggleViewed(uri: URI | undefined): Promise<void> {
        const target = uri ?? this.editorManager.currentEditor?.editor.getResourceUri();
        if (!target) {
            return;
        }
        const stat = await this.fileService.resolve(target).catch(() => undefined);
        if (stat?.isDirectory) {
            const coverage = await this.reviews.getCoverage();
            const folder = this.reviews.relativePath(target.toString());
            const area = coverage?.areas.find(a => a.path === folder || folder.startsWith(`${a.path}/`) || a.path.startsWith(`${folder}/`));
            this.messages.info(area ? `${area.viewed} of ${area.total} files viewed in ${area.path}.` : 'Mark files one by one: open each and press ⌘⌥V.');
            return;
        }
        await this.reviews.setViewed([target.toString()], !this.reviews.isViewed(target.toString()));
    }

    /** After the layout is restored (opening earlier would be undone by the restore). */
    async onDidInitializeLayout(): Promise<void> {
        await this.openStart();
        await this.welcome();
        // A review opened or switched to later (an agent's open_review, the switcher) starts the same way.
        // So does a review whose first findings just arrived (an agent's first pass, with the window already open).
        const unresolved = () => this.reviews.activeReview?.threads.filter(t => t.status !== 'resolved').length ?? 0;
        let active = this.reviews.activeReview?.id;
        let count = unresolved();
        this.reviews.onDidChange(() => {
            const id = this.reviews.activeReview?.id;
            const now = unresolved();
            const firstFindings = id === active && count === 0 && now > 0;
            count = now;
            if (id && (id !== active || firstFindings)) {
                active = id;
                this.openStart(true);
            }
        });
    }

    /**
     * A review never starts on an empty window: the explorer shows, and with no editor open the review's
     * document opens (a review directory), else the first open thread, the reviewed paths, the README or the
     * first file of the repository. `present` (a review just switched to, or its first findings just in): its first
     * thread opens even beside other editors.
     */
    protected async openStart(present = false): Promise<void> {
        await this.reviews.ready;
        const root = this.reviews.root;
        if (!root) {
            return;
        }
        const review = this.reviews.activeReview;
        await this.fileNavigator.openView({ activate: false, reveal: true });
        // A review that starts with findings (an agent's first pass) opens on them: the panel lists them all.
        if (review?.threads.some(t => t.status !== 'resolved')) {
            await this.openView({ activate: false, reveal: true });
        }
        // Every review opens on its overview page, except a design or knowledge bundle, which opens on its document.
        if (present && review && await this.openOverview()) {
            return;
        }
        if (this.shell.getWidgets('main').length) {
            return;
        }
        if (review && await this.openOverview()) {
            return;
        }
        const thread = review?.threads.find(t => t.status !== 'resolved' && t.location.uri && t.location.kind !== 'directory');
        if (review?.bundle) {
            await this.openBundleDocument();
            return;
        }
        if (thread) {
            await this.navigator.open(thread.location, thread.id);
            return;
        }
        const candidates = review?.scope.kind === 'paths' ? review.scope.uris.map(u => new URI(u)) : [];
        for (const uri of [...candidates, new URI(root)]) {
            const file = await this.firstFile(uri);
            if (file) {
                await open(this.openerService, file);
                return;
            }
        }
    }

    /** `uri` if it is a file; for a folder, its README or else its first file. */
    protected async firstFile(uri: URI): Promise<URI | undefined> {
        const stat = await this.fileService.resolve(uri, { resolveMetadata: false }).catch(() => undefined);
        if (!stat) {
            return undefined;
        }
        if (!stat.isDirectory) {
            return stat.resource;
        }
        const files = (stat.children ?? []).filter(c => c.isFile && !c.name.startsWith('.')).sort((a, b) => a.name.localeCompare(b.name));
        return (files.find(f => /^readme(\.(md|markdown|txt|rst))?$/i.test(f.name)) ?? files[0])?.resource;
    }

    /** The first time Co-Review runs, the Review panel opens, so a new user sees where to start. */
    protected async welcome(): Promise<void> {
        const key = 'co-review.welcomed';
        try {
            if (localStorage.getItem(key)) {
                return;
            }
            localStorage.setItem(key, '1');
        } catch {
            return;
        }
        await this.reviews.ready;
        if (!this.reviews.activeReview) {
            await this.openView({ reveal: true });
        }
    }

    /** A review directory opens on its document, or its first patch. */
    protected async openBundleDocument(): Promise<void> {
        await this.reviews.ready;
        const review = this.reviews.activeReview;
        if (!review?.bundle || this.shell.getWidgets('main').length) {
            return;
        }
        // The review directory, which isn't the window's folder when the review has code (see CodeFolders).
        const rootUri = URI.fromFilePath(review.bundle.dir);
        const root = rootUri.toString();
        let doc: string | undefined;
        for (const name of DOCUMENT_NAMES) {
            if (await this.fileService.exists(rootUri.resolve(name))) {
                doc = name;
                break;
            }
        }
        if (!doc) {
            const children = (await this.fileService.resolve(rootUri, { resolveMetadata: false }).catch(() => undefined))?.children ?? [];
            const names = children.map(c => c.name).sort();
            doc = names.find(n => n.endsWith('.pseudocode.md')) ?? names.find(n => /\.(patch|diff)$/.test(n));
        }
        if (doc) {
            await open(this.openerService, new URI(root).resolve(doc));
        }
    }

    override async openView(args?: Partial<OpenViewArguments>): Promise<ReviewWidget> {
        const widget = await super.openView(args);
        // First time on the right: give the panel a readable width.
        if (widget.isVisible && widget.node.clientWidth > 0 && widget.node.clientWidth < 320) {
            this.shell.resize(Math.max(360, Math.round(window.innerWidth * 0.28)), 'right');
        }
        return widget;
    }

