        server.registerTool('ask_reviewer', {
            description: 'Ask the reviewer to decide between options (shown as buttons in the thread), then wait as await_reviewer does. '
                + 'Their choice comes back as their message in that thread ({status:"comment"}, `question.choice` set); if they comment '
                + 'elsewhere, reply in the thread or submit first, you get that instead, and the choice comes later from await_reviewer.',
            inputSchema: {
                reviewId: reviewArg,
                question: z.string(),
                options: z.array(z.string()).min(1).max(6),
                threadId: z.string().optional().describe('Ask inside this thread; otherwise a repository-level thread is created'),
                timeoutSec: z.number().int().min(1).max(3600).optional()
            }
        }, async ({ reviewId, question, options, threadId, timeoutSec }, extra) => {
            const review = await resolveReview(reviewId);
            const inThread = review && threadId ? findThread(review, threadId.trim()) : undefined;
            if (!review) {
                return fail('No review. Call open_review first.');
            }
            if (threadId && !inThread) {
                return fail(`No thread "${threadId}".`);
            }
            const agent = this.agentOf(session);
            const thread = inThread ?? await this.store.createThread(review.id, { kind: 'repository' }, question, agent);
            const request = { id: randomUUID(), title: question, options: options.map((name, i) => ({ id: String(i), name, kind: 'allow_once' })) };
            const messageId = await this.store.startMessage(review.id, thread.id, agent, { body: inThread ? question : '', permission: request, status: 'done' });
            await this.store.setAgentState(review.id, thread.id, 'waiting_for_human');
            // The answer can come at any time, also after this call returned: it lands in the thread as the reviewer's
            // message, which await_reviewer delivers like any other.
            let choice: string | undefined;
            // A day, so an unanswered question isn't kept for the life of the app; then the buttons show it was cancelled.
            const recorded = this.decisions.wait(request.id, 24 * 60 * 60 * 1000).then(async optionId => {
                choice = optionId === undefined ? undefined : options[Number(optionId)];
                await this.store.updateMessage(review.id, thread.id, messageId, { permission: { ...request, outcome: optionId ?? 'cancelled' } });
                if (choice === undefined) {
                    await this.store.setAgentState(review.id, thread.id, 'idle');
                    return;
                }
                const answered = await this.store.addMessage(review.id, thread.id, `Chose: **${choice}**`, await currentUser(review.workspaceRoot), { choice });
                return answered.messages[answered.messages.length - 1].id;
            });
            recorded.catch(error => console.error('[co-review] recording the reviewer\'s choice failed', error));
            const result = await this.awaitReviewer(session, review, (timeoutSec ?? 900) * 1000, extra.signal);
            if (result.isError) {
                return result;
            }
            const payload = JSON.parse(result.content[0].text);
            if (choice !== undefined) {
                // This call returns the choice: it is delivered, not something to wait for again.
                const choiceMessage = await recorded.catch(() => undefined);
                if (choiceMessage) {
                    session.delivered.add(choiceMessage);
                    await this.store.setAgentState(review.id, thread.id, 'idle');
                }
            }
            return json({ ...payload, question: { threadId: threadRef(thread), status: choice === undefined ? 'pending' : 'answered', choice } });
        });

        server.registerTool('post_review_to_github', {
            description: 'Post the review to its GitHub pull request (a review directory whose PR.md has `repo: <owner>/<name>` and '
                + '`pr: <number>`), as one GitHub review: open threads on diff lines become line comments, each the reviewer\'s point '
                + 'only, not the discussion (suggested edits become GitHub suggestions), the rest goes into the review\'s body, and the reviewer\'s latest verdict is the review\'s decision. '
                + 'Only when the reviewer asks for it: Co-Review first shows them what will be posted and posts only if they confirm.',
            inputSchema: {
                reviewId: reviewArg,
                summary: z.string().optional().describe('The review\'s message on GitHub (default: the reviewer\'s summary from Submit review)'),
                comments: z.array(z.object({ threadId: z.string(), body: z.string() })).optional().describe('Each open comment as the '
                    + 'reviewer\'s own point, in their voice (threadId: its id or short id). Only what they want changed, as one comment '
                    + 'of theirs: not the discussion, not your replies, no mention of talking it over with you. A thread left out is '
                    + 'posted as the reviewer\'s own messages.')
            }
        }, async ({ reviewId, summary, comments }) => {
            const review = await resolveReview(reviewId);
            const target = await this.github.target(review);
            if (!review || !target) {
                return fail('This review is not a GitHub pull request: its review directory needs a PR.md with `repo: <owner>/<name>` and `pr: <number>`.');
            }
            const reworded = new Map<string, string>();
            for (const c of comments ?? []) {
                const thread = findThread(review, c.threadId.trim());
                if (!thread) {
                    return fail(`No thread "${c.threadId}".`);
                }
                if (c.body.trim()) {
                    reworded.set(thread.id, c.body.trim());
                }
            }
            const decision = review.verdict?.decision ?? 'comment';
            const composed = this.github.compose(review, decision, summary ?? review.verdict?.summary ?? '', reworded);
            const again = target.postedRound !== undefined && target.postedRound === (review.verdict?.count ?? 0)
                ? ` This round was already posted (${target.postedUrl}).` : '';
            const question = `Post this review to GitHub, ${target.repo}#${target.number}? As "${decision}", with ${composed.comments.length} line `
                + `comment${composed.comments.length === 1 ? '' : 's'}${composed.elsewhere ? ` and ${composed.elsewhere} in the review's body` : ''}.${again}`;
            const agent = this.agentOf(session);
            const thread = await this.store.createThread(review.id, { kind: 'repository' }, question, agent);
            const request = { id: randomUUID(), title: question, options: [{ id: 'post', name: 'Post to GitHub', kind: 'allow_once' }, { id: 'skip', name: 'Don\'t post', kind: 'reject_once' }] };
            // Exactly what goes out, so the reviewer confirms the words, not just the counts.
            const preview = previewMarkdown(await this.github.preview(review.id, decision, summary, reworded));
            const messageId = await this.store.startMessage(review.id, thread.id, agent, { body: `This is what will be posted:\n\n${preview}`, permission: request, status: 'done' });
            await this.store.setAgentState(review.id, thread.id, 'waiting_for_human');
            const choice = await this.decisions.wait(request.id, 15 * 60 * 1000);
            await this.store.updateMessage(review.id, thread.id, messageId, { permission: { ...request, outcome: choice ?? 'cancelled' } });
            await this.store.setAgentState(review.id, thread.id, 'idle');
            if (choice !== 'post') {
                await this.store.setThreadStatus(review.id, thread.id, 'resolved', agent).catch(() => undefined);
                return json({ status: choice === undefined ? 'pending' : 'declined', hint: 'Nothing was posted. Don\'t post unless the reviewer asks again.' });
            }
            try {
                const posted = await this.github.publish(review.id, decision, summary, reworded);
                await this.store.addMessage(review.id, thread.id, `Posted to GitHub: ${posted.url}`, agent);
                await this.store.setThreadStatus(review.id, thread.id, 'resolved', agent).catch(() => undefined);
                return json({ status: 'posted', ...posted });
            } catch (e) {
                await this.store.addMessage(review.id, thread.id, `Posting to GitHub failed: ${e instanceof Error ? e.message : e}`, agent);
                return fail(e instanceof Error ? e.message : String(e));
            }
        });

