     * thread opens even beside other editors.
     */
    protected async openStart(present = false): Promise<void> {
        await this.reviews.ready;
        const root = this.reviews.root;
        if (!root) {
            return;
        }
        const review = this.reviews.activeReview;
        await this.fileNavigator.openView({ activate: false, reveal: true });
        // A review that starts with findings (an agent's first pass) opens on them: the panel lists them all.
        if (review?.threads.some(t => t.status !== 'resolved')) {
            await this.openView({ activate: false, reveal: true });
        }
        // Every review opens on its overview page, except a design or knowledge bundle, which opens on its document.
        if (present && review && await this.openOverview()) {
            return;
        }
        if (this.shell.getWidgets('main').length) {
            return;
        }
        if (review && await this.openOverview()) {
            return;
        }
        const thread = review?.threads.find(t => t.status !== 'resolved' && t.location.uri && t.location.kind !== 'directory');
        if (review?.bundle) {
            await this.openBundleDocument();
            return;
        }
        if (thread) {
            await this.navigator.open(thread.location, thread.id);
            return;
        }
        const candidates = review?.scope.kind === 'paths' ? review.scope.uris.map(u => new URI(u)) : [];
        for (const uri of [...candidates, new URI(root)]) {
            const file = await this.firstFile(uri);
            if (file) {
                await open(this.openerService, file);
                return;
            }
        }
    }

    /** `uri` if it is a file; for a folder, its README or else its first file. */
    protected async firstFile(uri: URI): Promise<URI | undefined> {
        const stat = await this.fileService.resolve(uri, { resolveMetadata: false }).catch(() => undefined);
        if (!stat) {
            return undefined;
        }
        if (!stat.isDirectory) {
            return stat.resource;
        }
        const files = (stat.children ?? []).filter(c => c.isFile && !c.name.startsWith('.')).sort((a, b) => a.name.localeCompare(b.name));
        return (files.find(f => /^readme(\.(md|markdown|txt|rst))?$/i.test(f.name)) ?? files[0])?.resource;
    }

    /** The first time Co-Review runs, the Review panel opens, so a new user sees where to start. */
    protected async welcome(): Promise<void> {
        const key = 'co-review.welcomed';
        try {
            if (localStorage.getItem(key)) {
                return;
            }
            localStorage.setItem(key, '1');
        } catch {
            return;
        }
        await this.reviews.ready;
        if (!this.reviews.activeReview) {
            await this.openView({ reveal: true });
        }
    }

    /** A review directory opens on its document, or its first patch. */
    protected async openBundleDocument(): Promise<void> {
        await this.reviews.ready;
        const review = this.reviews.activeReview;
        if (!review?.bundle || this.shell.getWidgets('main').length) {
            return;
        }
        // The review directory, which isn't the window's folder when the review has code (see CodeFolders).
        const rootUri = URI.fromFilePath(review.bundle.dir);
        const root = rootUri.toString();
        let doc: string | undefined;
        for (const name of DOCUMENT_NAMES) {
            if (await this.fileService.exists(rootUri.resolve(name))) {
                doc = name;
                break;
            }
        }
        if (!doc) {
            const children = (await this.fileService.resolve(rootUri, { resolveMetadata: false }).catch(() => undefined))?.children ?? [];
            const names = children.map(c => c.name).sort();
            doc = names.find(n => n.endsWith('.pseudocode.md')) ?? names.find(n => /\.(patch|diff)$/.test(n));
        }
        if (doc) {
            await open(this.openerService, new URI(root).resolve(doc));
        }
    }

    override async openView(args?: Partial<OpenViewArguments>): Promise<ReviewWidget> {
        const widget = await super.openView(args);
        // First time on the right: give the panel a readable width.
        if (widget.isVisible && widget.node.clientWidth > 0 && widget.node.clientWidth < 320) {
            this.shell.resize(Math.max(360, Math.round(window.innerWidth * 0.28)), 'right');
        }
        return widget;
    }

