        this.title.closable = true;
        this.title.iconClass = codicon('comment-discussion');
        this.addClass('co-review');
        this.node.tabIndex = 0;
        this.toDispose.push(this.reviews.onDidChange(() => {
            this.update();
            this.refreshCoverage();
