            if (thread && this.filter !== 'all' && thread.status !== this.filter) {
                this.filter = 'all';
            }
            this.pendingScroll = true;
            this.update();
        }));
        this.update();
        this.refreshCoverage();
    }

    protected refreshCoverage(): void {
        window.clearTimeout(this.coverageTimer);
