    installCli(): Promise<string>;
}

export interface ReviewClient {
    onAgentPresence(presence: AgentPresence): void;
    onReviewChanged(review: Review): void;
    onReviewDeleted(reviewId: string, workspaceRoot: string): void;
    /**
